#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define rot(a)    mat2(cos(a+vec4(0,11,33,0)))        // rotation
#define H3(p)      fract(sin(dot(p, R2-12.7+cos(iTime))) * 4.)   // hash

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec3 p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  
    vec4 O2 =O;
    vec2 U= C;
    vec3  R2 = iResolution, Y = vec3(0,1,0),
          D = normalize(vec3((U+U-R2.xy)/R2.y, -3.)),   // ray direction
          p2 = vec3(0,0,52), q2,a2,i2,d2,                  // marching point along ray 
          M = iMouse.z > 0. ? iMouse.xyz/R2 -.5: vec3(10,12,0)/1e2*cos(iTime+vec3(0,11,0))+vec3(0,.12,0); 
float t=2.; 
    for ( O2=vec4(1); O2.x > 0. && t > .005; O2-=.01 ) {
        q2 = p2,



        a2 = abs(q2), i2 = floor(q2),
        q = fract(q2)-.5;      
        q2.yz *= rot(iTime),  
          q2.xy *= rot(iTime),// rotations
        q2.xz *= rot(-iTime),// cells
         t = min(t, abs(q2[int(3.*H3(i2))])-.21 ),       // random wall
         t = max( t, max(a2.x, max(a2.y,a2.z))-10. ),     // clamp to cube

        p2 += 0.25*t*D;                                  // step forward = dist to obj
    }


    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(1),H(g*.1),.8)*1./e/8e3
    )
    {
        p=g*d;


        a=30.;
        p=mod(p-a,a*2.)-a;
        s=2.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.01)*.1;
            p=abs(p)*e-
                vec3(
                    5.*3.,
                    120,
                    8.+5.
                 )*O2.xyz;
         }
         g+=e=length(p.yz)/s;
    }
    O+=O2;
}
